package vn.hust.restaurant.repository;
import java.sql.*;import java.util.*;import vn.hust.restaurant.config.Database;import vn.hust.restaurant.model.Customer;
public class CustomerRepository{
 public List<Customer> findAll(String k)throws SQLException{List<Customer>o=new ArrayList<>();k=k==null?"":k;String s="SELECT MaKhachHang,MaKhachHangCode,HoTen,SDT,Email,DiemTichLuy,TrangThai FROM KhachHang WHERE (?='' OR HoTen LIKE '%'+?+'%' OR SDT LIKE '%'+?+'%') ORDER BY HoTen";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setString(1,k);p.setString(2,k);p.setString(3,k);try(ResultSet r=p.executeQuery()){while(r.next())o.add(new Customer(r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getInt(6),r.getString(7)));}}return o;}
 public void save(Customer x)throws SQLException{String s=x.id()==0?"INSERT KhachHang(MaKhachHangCode,HoTen,SDT,Email,DiemTichLuy,TrangThai) VALUES(?,?,?,?,?,'HOAT_DONG')":"UPDATE KhachHang SET MaKhachHangCode=?,HoTen=?,SDT=?,Email=?,DiemTichLuy=?,TrangThai=? WHERE MaKhachHang=?";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setString(1,x.code());p.setString(2,x.fullName());p.setString(3,x.phone());p.setString(4,x.email());p.setInt(5,x.points());if(x.id()!=0){p.setString(6,x.status());p.setInt(7,x.id());}p.executeUpdate();}}
 public void deactivate(int id)throws SQLException{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("UPDATE KhachHang SET TrangThai='NGUNG_HOAT_DONG' WHERE MaKhachHang=?")){p.setInt(1,id);p.executeUpdate();}}
}
